#!/usr/bin/env python3
"""Recompute deterministic Merapi 2010 pressure-index ground truth."""

from __future__ import annotations

import html
import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-307_Q1"
PACKAGE_ID = "CSX-307"
TARGET_FAMILY = "merapi_2010_pyroclastic_lahar_ash_rain_pressure_index"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_Merapi_eruption.json",
    "data/other/other_002_01_anchor.html.html",
    "data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json",
]



DEEPENED_TASK_FRAME = {'bounded_prompt': 'Do not infer exact lahar discharge, plume mass, eruption dynamics, or evacuation outcomes unless '
                   'directly sourced.',
 'decisive_evidence_prompt': 'The strongest answer links volcanic forcing with ash, lahar, rainfall, or surface '
                             'signals rather than isolating one product.',
 'group': 'deepened_remaining_39',
 'mechanism_chain': ['eruption or pyroclastic anchor',
                     'ash or surface signal',
                     'rainfall-lahar modifier',
                     'single-hazard rejection'],
 'mechanism_question': 'diagnose whether multiple volcanic processes and rainfall modifiers form a compound pressure '
                       'chain',
 'new_title': 'Merapi Compound Pyroclastic-Lahar-Ash Pressure Diagnosis',
 'rejected_prompt': 'Reject ash-only, rain-only, or image-only explanations if a compound volcanic chain is required.',
 'target_family': 'compound_volcanic_pressure_diagnosis',
 'task_mode': 'deep_mechanism_diagnosis'}

def _deep_rename_key(key):
    replacements = [
        ("score_ledger", "evidence_rows"),
        ("ledger_rows", "evidence_rows"),
        ("ledger", "evidence_synthesis"),
        ("Ledger", "EvidenceSynthesis"),
        ("consistency", "process_alignment"),
        ("Consistency", "ProcessAlignment"),
        ("threshold", "diagnostic_gate"),
        ("Threshold", "DiagnosticGate"),
        ("gate", "diagnostic_test"),
        ("Gate", "DiagnosticTest"),
        ("score_breakdown", "evidence_score_breakdown"),
        ("score", "evidence_score"),
        ("Score", "EvidenceScore"),
    ]
    out = str(key)
    for old, new in replacements:
        out = out.replace(old, new)
    return out


def _deep_rename_obj(value, parent_key=None):
    protected_value_keys = {
        "answer",
        "final_label",
        "classification",
        "label",
        "diagnosis",
        "result",
        "answer_type",
        "task_family",
        "target_family",
    }
    if isinstance(value, dict):
        return {_deep_rename_key(k): _deep_rename_obj(v, k) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_rename_obj(v, parent_key) for v in value]
    if isinstance(value, str):
        if parent_key in protected_value_keys:
            return value
        out = value
        replacements = [
            ("ledger", "evidence synthesis"),
            ("Ledger", "Evidence synthesis"),
            ("consistency", "process alignment"),
            ("Consistency", "Process alignment"),
            ("threshold", "diagnostic gate"),
            ("Threshold", "Diagnostic gate"),
        ]
        for old, new in replacements:
            out = out.replace(old, new)
        return out
    return value

def _deep_extract_answer(value):
    if isinstance(value, dict):
        for key in ("final_label", "answer", "classification", "label", "final_interpretation", "diagnosis"):
            if key in value and isinstance(value[key], (str, int, float, bool)):
                return str(value[key])
        for key in ("classification", "threshold_result", "result"):
            if key in value and isinstance(value[key], dict):
                nested = _deep_extract_answer(value[key])
                if nested:
                    return nested
    return "deep_mechanism_diagnosis"


def apply_deepened_task_frame(result):
    frame = dict(DEEPENED_TASK_FRAME)
    old_primary = result.get("primary_gt")
    if not isinstance(old_primary, dict):
        old_primary = {"value": old_primary}
    transformed = {
        "answer": frame.get("answer_override", _deep_extract_answer(old_primary)),
        "task_mode": frame["task_mode"],
        "mechanism_question": frame["mechanism_question"],
        "computed_evidence": _deep_rename_obj(old_primary),
        "mechanism_chain": list(frame["mechanism_chain"]),
        "decisive_evidence": frame["decisive_evidence_prompt"],
        "rejected_simplifications": frame["rejected_prompt"],
        "bounded_interpretation": frame["bounded_prompt"],
    }
    if frame.get("formula_prompt"):
        transformed["formula_derivation"] = frame["formula_prompt"]
    if isinstance(transformed.get("computed_evidence"), dict):
        for stale_key in ("answer", "answer_type", "target_family", "task_family"):
            transformed["computed_evidence"].pop(stale_key, None)
    result["primary_gt"] = transformed
    result["task_type"] = "structured_reasoning"
    result["evaluation_mode"] = "hybrid"
    result["subtype"] = frame["task_mode"]
    result["target_family"] = frame.get("target_family", frame["task_mode"])
    result["deepened_reframe"] = {
        "group": frame["group"],
        "replaces_table_only_task": True,
        "new_title": frame["new_title"],
    }
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["structured_answer"] = transformed
        guidance["answer"] = transformed["answer"]
    else:
        result["answer_guidance"] = {"structured_answer": transformed, "answer": transformed["answer"]}
    result["rubric"] = {
        "total_points": 20,
        "criteria": [
            {"name": "mechanism_diagnosis", "points": 4, "description": "Identifies the dominant physical process and gives the correct compact answer label or an equivalent diagnosis."},
            {"name": "computed_evidence", "points": 5, "description": "Recomputes the quantitative evidence inherited from the original task and preserves units, signs, ratios, and key values."},
            {"name": "evidence_weighting", "points": 4, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
            {"name": "counterfactual_rejection", "points": 3, "description": "Rejects at least one tempting simplified explanation using the computed values rather than assertion."},
            {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
            {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table or same-scale checklist."},
        ],
    }
    if frame.get("formula_prompt"):
        result["rubric"] = {
            "total_points": 20,
            "criteria": [
                {"name": "mechanism_diagnosis", "points": 3, "description": "Identifies the dominant physical process and gives the correct compact mechanism label or equivalent diagnosis."},
                {"name": "computed_evidence", "points": 4, "description": "Recomputes the package-derived quantitative evidence with correct units, signs, ratios, dates, and rounding."},
                {"name": "formula_derivation", "points": 3, "description": "Shows the requested physical formula, scaling relation, or timing relation and connects it to the computed values."},
                {"name": "evidence_weighting", "points": 3, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
                {"name": "counterfactual_rejection", "points": 3, "description": "Rejects tempting simplified explanations using computed values rather than assertion."},
                {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
                {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table."},
            ],
        }

    return result

def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def task_dir() -> Path:
    return Path(__file__).resolve().parent


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8-sig"))


def html_to_text(root: Path, rel_path: str) -> str:
    raw = (root / rel_path).read_text(encoding="utf-8", errors="ignore")
    text = re.sub(r"(?is)<script.*?</script>|<style.*?</style>", " ", raw)
    text = re.sub(r"(?s)<[^>]+>", " ", text)
    return re.sub(r"\s+", " ", html.unescape(text)).strip()


def snippet_after(text: str, heading: str, chars: int) -> str:
    start = text.find(heading)
    if start < 0:
        raise ValueError(f"missing report heading: {heading}")
    return text[start : start + chars]


def numbers(pattern: str, text: str) -> list[float]:
    out: list[float] = []
    for match in re.finditer(pattern, text, flags=re.I):
        for group in match.groups():
            if group:
                out.append(float(group.replace(",", "")))
                break
    return out


def rounded(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Answer form",
                "points": 3,
                "description": "Returns the requested compact JSON shape with target family, metrics, tests, classification, and one short computed consequence.",
                "partial_credit": "Award 1-2 points if the values are recoverable but field names or nesting differ.",
            },
            {
                "name": "Report anchors",
                "points": 4,
                "description": "Correctly extracts the 20 km hazard-zone radius, 18.3 km ash altitude, and 16.5 km maximum lahar-deposit distance.",
                "partial_credit": "Award partial credit for each correct anchor; no credit for replacing the report anchors with unrelated event-window values.",
            },
            {
                "name": "Reach and exposure calculations",
                "points": 4,
                "description": "Computes ash_excess_km = 6.3, lahar_zone_ratio = 0.825, and pop_m = 11.071 within tolerance.",
                "partial_credit": "Award about 1 point for each correct derived value and 1 point for correct units or unit-implied names.",
            },
            {
                "name": "Rain aggregation",
                "points": 4,
                "description": "Computes rain_mean_mm = 365.768, rain_peak_mean_mm = 537.7, and rain_conc = 1.47 within tolerance.",
                "partial_credit": "Award about 1 point for each correct rain component and 1 point for using the stated ratio formula.",
            },
            {
                "name": "Gate score",
                "points": 3,
                "description": "Applies all six threshold gates correctly and reports score = 6.",
                "partial_credit": "Award 0.5 point for each correctly evaluated gate.",
            },
            {
                "name": "Computed consequence",
                "points": 2,
                "description": "Returns compound_volcanic_pressure_high and keeps the consequence short and tied to the computed score.",
                "partial_credit": "Award 1 point for the correct classification with a vague or missing consequence.",
            },
        ],
    }


def build_output() -> dict[str, Any]:
    root = package_root()
    event = read_json(root, "metadata/event.json")
    anchor = read_json(root, "data/event_reports/event_reports_003_Locked_event_anchor_Merapi_eruption.json")
    worldpop = read_json(root, "data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json")
    era5 = read_json(root, "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json(root, "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json(root, "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json")
    report_text = html_to_text(root, "data/other/other_002_01_anchor.html.html")

    nov3 = snippet_after(report_text, "3 November-9 November 2010", 5200)
    nov10 = snippet_after(report_text, "10 November-16 November 2010", 2200)

    hazard_zone_radius_km = max(numbers(r"([0-9]+(?:\.[0-9]+)?)-km[- ]radius", nov3))
    highest_ash_altitude_km_asl = max(
        numbers(r"altitude(?:s)? of ([0-9]+(?:\.[0-9]+)?) km", nov3)
    )
    maximum_lahar_deposit_distance_km = max(
        numbers(r"maximum distance of ([0-9]+(?:\.[0-9]+)?) km", nov10)
    )

    rain_mean_inputs = {
        "era5_mean": float(era5["stats"]["precipitation_sum_mm_mean"]),
        "gpm_mean": float(gpm["stats"]["gpm_event_precip_mm_mean"]),
        "chirps_mean": float(chirps["stats"]["chirps_event_precip_mm_mean"]),
    }
    rain_peak_inputs = {
        "era5_max": float(era5["stats"]["precipitation_sum_mm_max"]),
        "gpm_max": float(gpm["stats"]["gpm_event_precip_mm_max"]),
        "chirps_max": float(chirps["stats"]["chirps_event_precip_mm_max"]),
    }

    raw_rain_mean = sum(rain_mean_inputs.values()) / len(rain_mean_inputs)
    raw_rain_peak_mean = sum(rain_peak_inputs.values()) / len(rain_peak_inputs)
    population = float(worldpop["population_sum"]["population"])

    thresholds = {
        "pyro_km": 20,
        "ash_excess_km": 6,
        "lahar_ratio": 0.8,
        "rain_mean_mm": 300,
        "rain_conc": 1.4,
        "pop_m": 10,
        "score": 5,
    }
    metrics = {
        "ash_excess_km": rounded(highest_ash_altitude_km_asl - 12),
        "lahar_zone_ratio": rounded(maximum_lahar_deposit_distance_km / hazard_zone_radius_km),
        "rain_mean_mm": rounded(raw_rain_mean),
        "rain_peak_mean_mm": rounded(raw_rain_peak_mean),
        "rain_conc": rounded(raw_rain_peak_mean / raw_rain_mean),
        "pop_m": rounded(population / 1_000_000),
    }
    tests = {
        "pyro": hazard_zone_radius_km >= thresholds["pyro_km"],
        "ash": metrics["ash_excess_km"] >= thresholds["ash_excess_km"],
        "lahar": metrics["lahar_zone_ratio"] >= thresholds["lahar_ratio"],
        "rain_load": metrics["rain_mean_mm"] >= thresholds["rain_mean_mm"],
        "rain_conc": metrics["rain_conc"] >= thresholds["rain_conc"],
        "pop": metrics["pop_m"] >= thresholds["pop_m"],
    }
    score = sum(1 for passed in tests.values() if passed)
    metrics["score"] = score
    classification = (
        "compound_volcanic_pressure_high"
        if score >= thresholds["score"]
        else "compound_volcanic_pressure_not_high"
    )

    tolerances = {
        "ash_excess_km": 0.01,
        "lahar_zone_ratio": 0.001,
        "rain_mean_mm": 0.001,
        "rain_peak_mean_mm": 0.001,
        "rain_conc": 0.001,
        "pop_m": 0.001,
        "score": 0,
    }

    primary_gt = {
        "answer": classification,
        "target_family": TARGET_FAMILY,
        "metrics": metrics,
        "tests": tests,
        "thr": thresholds,
        "tol": tolerances,
        "rejected": "rain_only_lahar_dominance",
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "target_family": TARGET_FAMILY,
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "event": {
            "package_id": PACKAGE_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": (
                f"{anchor['locked_event_anchor']['event_start_date']} to "
                f"{anchor['locked_event_anchor']['event_end_date']}"
            ),
            "location": anchor["locked_event_anchor"]["event_location"],
        },
        "decision_rule": {
            "summary": "Compute six Merapi pressure gates from report reach, ash height, lahar reach, precipitation aggregation, concentration ratio, and population.",
            "requires_computation": True,
            "score_rule": "The high-pressure label requires at least five passed gates; this event passes six.",
            "final_label": classification,
        },
        "key_values": {
            "report_anchors": {
                "hazard_zone_radius_km": hazard_zone_radius_km,
                "highest_ash_altitude_km_asl": highest_ash_altitude_km_asl,
                "maximum_lahar_deposit_distance_km": maximum_lahar_deposit_distance_km,
            },
            "precipitation_inputs_mm": {
                "means": {key: rounded(value) for key, value in rain_mean_inputs.items()},
                "maxima": {key: rounded(value) for key, value in rain_peak_inputs.items()},
            },
            "analysis_area_population": rounded(population),
            "derived_metrics": metrics,
            "gate_tests": tests,
        },
        "numeric_tolerances": {
            key: {"target": value, "absolute_tolerance": tolerances[key]}
            for key, value in metrics.items()
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "notes": "All scored values are recomputed from local CSX-307 report anchors, gridded precipitation summaries, and population total.",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    output = build_output()
    apply_deepened_task_frame(output)
    (task_dir() / "computed_gt.json").write_text(
        json.dumps(output, ensure_ascii=True, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
